module div_8bit(
    input clk, rst, sign, opn_valid, res_ready,
    input [7:0] dividend, divisor,
    output res_valid,
    output [15:0] result
);
// Add your code here
// Internal signals
reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [15:0] result_reg;
reg [3:0] cnt;
reg [3:0] start_cnt;
reg [15:0] SR;
reg [7:0] NEG_DIVISOR;
reg [7:0] temp_result;
reg [7:0] selected_result;
reg [7:0] CARRY_OUT;
reg [7:0] SHIFT_REGISTER;
// Sequential logic block
always @(posedge clk or posedge rst) begin
    if (rst) begin
        cnt <= 0;
        start_cnt <= 0;
    end else if (opn_valid && !res_valid) begin
        dividend_reg <= dividend;
        divisor_reg <= divisor;
        result_reg <= {8'h00, dividend};
        cnt <= 1;
        start_cnt <= 1;
    end else if (start_cnt) begin
        if (cnt[3]) begin
            cnt <= 0;
            start_cnt <= 0;
            result_reg <= {SR[15:8], SR[7:0]};
        end else begin
            cnt <= cnt + 1;
            case ({CARRY_OUT})
                8'd0: begin
                    selected_result = SR[15:8];
                    CARRY_OUT = 0;
                end
                default: begin
                    selected_result = SR[15:8] - 1;
                    CARRY_OUT = 1;
                end
            endcase
            SHIFT_REGISTER = {selected_result, SR[7:1]};
            SR <= {SHIFT_REGISTER, SR[0]};
        end
    end
end
// Combinational logic block
assign res_valid = (rst || cnt == 8) ? 1'b0 :
                   (res_valid && res_ready) ? 1'b0 : 1'b1;
assign result = result_reg;
endmodule
